INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:codex:cli-surface-v1','project_tool','seed://codex/cli-surface','Codex CLI command surface','Snapshot date: 2026-07-15. Commands and tools: /help, /status, /model, /approvals, /permissions, /compact, /review, /diff, /mention, /mcp, /logout; codex exec, resume, fork, apply, review, cloud, mcp. Configuration model: ~/.codex/config.toml; mcp_servers.<name> entries; project AGENTS.md governs local instructions. Source: docs/codex_cli_slash_commands.md and src/codex_parity_154x.rs.','docs/codex_cli_slash_commands.md and src/codex_parity_154x.rs','a0ae9243e4a426735d6cbb0b083c9f15d7ea34403ee057f28f873229f790e7fa','codex,cli,command-surface,provenance',2.2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:codex:config-model-v1','project_doc','seed://codex/config-model','Codex CLI command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: ~/.codex/config.toml; mcp_servers.<name> entries; project AGENTS.md governs local instructions. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: docs/codex_cli_slash_commands.md and src/codex_parity_154x.rs.','docs/codex_cli_slash_commands.md and src/codex_parity_154x.rs','7a6d28ede171c8588f062d74404acfe7799f3279a30db8066c8adef76799e288','codex,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:codex:integration-points-v1','project_doc','seed://codex/integration','Codex CLI command surface Simplicio integration points','Snapshot date: 2026-07-15. T2 MCP plus rules; registration must be additive and TOML-safe. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: docs/codex_cli_slash_commands.md and src/codex_parity_154x.rs.','docs/codex_cli_slash_commands.md and src/codex_parity_154x.rs','8bff483e2835666a4a90899b8a4880346cdbec2f2490edb4a04d0b9038879285','codex,simplicio,integration,governance',2);
